import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.Cd-3tpCq.js";const c=JSON.parse('{"title":"buddyGenAI Options","description":"","frontmatter":{},"headers":[],"relativePath":"options.md","filePath":"options.md"}'),i={name:"options.md"};function s(n,e,l,d,h,u){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="buddygenai-options" tabindex="-1">buddyGenAI Options <a class="header-anchor" href="#buddygenai-options" aria-label="Permalink to &quot;buddyGenAI Options&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><ul><li><strong>Tab Icons</strong>: Whether to display icons for the sidebar tabs. Disable to show text labels instead.</li><li><strong>Color Mode</strong>: Whether to use <strong>Light</strong> or <strong>Dark</strong> mode, or use the <strong>System-preferred</strong> mode.</li><li><strong>Your Name</strong>: This will show up in-chat and control how your buddies refer to you.</li><li><strong>Profile Image</strong>: Set a profile image for yourself to show in chat messages.</li><li><strong>Your Description</strong>: Info about you/the user, which will be provided for extra context when chatting with buddies or the Assistant.</li></ul><h2 id="ai-providers" tabindex="-1">AI Providers <a class="header-anchor" href="#ai-providers" aria-label="Permalink to &quot;AI Providers&quot;">​</a></h2><p>At the top of this section, you&#39;ll find 4 dropdowns for the features the app supports, allowing you to set which provider handles certain things or Disable them.</p><p>These dropdowns and their supported providers are:</p><ul><li><strong>Chat</strong>: KoboldCpp / WebLLM / OpenRouter</li><li><strong>Image</strong>: KoboldCpp</li><li><strong>TTS</strong>: KoboldCpp</li><li><strong>Transcription</strong>: KoboldCpp</li></ul><p>Providers that are selected above will display below in order to configure them. Below is info about how each AI Provider can be configured in this panel:</p><ul><li><strong>KoboldCpp</strong>: Currently you can just set a <strong>Host</strong> (if you&#39;re using something besides the default). Once a valid Host is set, you should see a list of features that the KoboldCpp instance supports.</li><li><strong>WebLLM</strong>: If enabled, then a dropdown and button will be available to choose and load a chat model (which will be downloaded the first time, should load faster next time)</li><li><strong>OpenRouter</strong>: If enabled, a text box will display to view or edit your connected API key. If there&#39;s no API key value in the box, then a &quot;Connect to OpenRouter&quot; button which will take you to <a href="https://openrouter.ai" target="_blank" rel="noreferrer">https://openrouter.ai</a> to login &amp; get an API key.</li></ul><h2 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h2><ul><li><strong>Stream AI Responses</strong>: Control whether messages are typed out as it&#39;s received. When disabled, Assistant/Buddy messages will show <code>{Name} is typing...</code> until the entire message is received.</li></ul><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><h3 id="text-to-speech" tabindex="-1">Text-to-Speech <a class="header-anchor" href="#text-to-speech" aria-label="Permalink to &quot;Text-to-Speech&quot;">​</a></h3><ul><li>Default Voice</li><li>Auto-Read Chat: Once messages are received, automatically generate &amp; play them with TTS.</li></ul><h3 id="transcription" tabindex="-1">Transcription <a class="header-anchor" href="#transcription" aria-label="Permalink to &quot;Transcription&quot;">​</a></h3><ul><li>Auto-Send after recording: Whether to automatically send your input after recording + transcription is finished.</li></ul><h2 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h2><ul><li><strong>Enable Chat Images</strong>: Feature to allow Assistant/Buddies to generate + send an image as part of a message. Generated images are at 512x768 resolution instead of the square 512px profile pictures. <ul><li>When enabled, you&#39;ll see&#39; <strong>Chat Image Quality</strong> which changes how many steps are used to generate images.</li><li>This isn&#39;t implemented well &amp; makes performance pretty bad. <strong>I don&#39;t recommend using this feature</strong> (all the time at least) <strong>yet</strong>.</li></ul></li></ul>',18)]))}const g=t(i,[["render",s]]);export{c as __pageData,g as default};
